{
  "optimization_problem_type": "Product Mix",
  "objective": {
    "goal": "Maximize Total Profit",
    "mathematical_formulation": "Maximize Z = Σ_{i=1}^{50} (Profit_Per_Unit_i × x_i)"
  },
  "decision_variables": {
    "definition": "x_i = number of units of Product_ID i to produce",
    "domain": "x_i ≥ 0 (continuous for LP relaxation; integer if production batches are indivisible)"
  },
  "constraints": {
    "resource_limits": {
      "description": "Aggregate resource consumption across all products must not exceed available capacity.",
      "mathematical_formulation": [
        "Σ_{i=1}^{50} (Machine_A_Hours_Req_i × x_i) ≤ Capacity_A",
        "Σ_{i=1}^{50} (Machine_B_Hours_Req_i × x_i) ≤ Capacity_B",
        "Σ_{i=1}^{50} (Labor_Hours_Req_i × x_i) ≤ Capacity_Labor",
        "Σ_{i=1}^{50} (Raw_Material_Units_Req_i × x_i) ≤ Capacity_RawMaterial"
      ]
    },
    "demand_limits": {
      "description": "Production volume for each product must respect contractual minimums and market ceilings.",
      "mathematical_formulation": "Min_Production_Requirement_i ≤ x_i ≤ Max_Market_Demand_i, ∀ i ∈ {1,...,50}"
    }
  },
  "capacity_definition_strategy": {
    "issue_identified": "The CSV dataset provides per-unit resource requirements and demand bounds, but completely lacks the total available capacities (Capacity_A, Capacity_B, Capacity_Labor, Capacity_RawMaterial) required to close the constraint system.",
    "proposed_method": "Estimate capacities internally by assuming they are constrained to 80% of the total resource demand if every product were produced at its maximum market demand. This creates a realistic, binding bottleneck scenario typical in production planning.",
    "calculation_formula": [
      "Capacity_A = 0.80 × Σ_{i=1}^{50} (Machine_A_Hours_Req_i × Max_Market_Demand_i)",
      "Capacity_B = 0.80 × Σ_{i=1}^{50} (Machine_B_Hours_Req_i × Max_Market_Demand_i)",
      "Capacity_Labor = 0.80 × Σ_{i=1}^{50} (Labor_Hours_Req_i × Max_Market_Demand_i)",
      "Capacity_RawMaterial = 0.80 × Σ_{i=1}^{50} (Raw_Material_Units_Req_i × Max_Market_Demand_i)"
    ],
    "rationale": "Setting capacity to 80% guarantees the problem is feasible (since 100% demand would exceed capacity) while forcing the optimizer to make meaningful trade-offs between high-margin and resource-intensive products. This approach leverages existing dataset columns to derive realistic limits without requiring external data or manual parameter tuning."
  }
}
```

